contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry performing setFeeRate and asserting the general rule
    function run(uint16 newFeeRate) public payable {
        // precondition: caller (this contract) must be the pool owner to avoid revert from onlyOwner
        // The checker deploys a fresh C and mints ownership to Factory owner; we require newFeeRate <= 5000
        require(newFeeRate <= 5000, "feeRate too large");

        // observe before value of feeRate and virtualBaseTokenReserves
        uint16 beforeFee = c.feeRate(); if (__ESBMC_reverted()) return;
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;

        // perform the state-changing call: must be a top-level statement
        bool reverted;
        c.setFeeRate(newFeeRate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after values
        uint16 afterFee = c.feeRate(); if (__ESBMC_reverted()) return;
        uint128 afterVirtualBase = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;

        // General rule: if setFeeRate was not reverted then feeRate equals newFeeRate and virtualBaseTokenReserves unchanged
        assert(reverted || (afterFee == newFeeRate && afterVirtualBase == beforeVirtualBase));
    }

    receive() external payable {}
}

