pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint16 newFeeRate) internal {
        newFeeRate = uint16(bound(uint256(newFeeRate), 0, 5000));
        uint16 beforeFee;
        try c.feeRate() returns (uint16 __r) { beforeFee = __r; } catch { return; }
        uint128 beforeVirtualBase;
        try c.virtualBaseTokenReserves() returns (uint128 __r) { beforeVirtualBase = __r; } catch { return; }
        bool reverted;
        try c.setFeeRate(newFeeRate) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint16 afterFee;
        try c.feeRate() returns (uint16 __r) { afterFee = __r; } catch { return; }
        uint128 afterVirtualBase;
        try c.virtualBaseTokenReserves() returns (uint128 __r) { afterVirtualBase = __r; } catch { return; }
        assertTrue(reverted || (afterFee == newFeeRate && afterVirtualBase == beforeVirtualBase));
    }

    function testFuzz_run(uint16 newFeeRate) public {
        _run(newFeeRate);
    }

    receive() external payable {}
}
